package local.station.controller;

import android.app.*;import android.content.*;import android.net.Uri;import android.os.*;import android.util.Base64;import android.view.*;import android.widget.*;import org.json.*;
import java.io.*;import java.net.*;import java.security.*;import java.security.cert.*;import javax.net.ssl.*;

/** Public OAuth client with S256 PKCE. Passwords stay in the Yandex browser. */
public final class YandexHomeActivity extends Activity {
 static final String REDIRECT="alicekit://oauth/yandex";private TextView message;private boolean running;
 @Override public void onCreate(Bundle saved){super.onCreate(saved);LinearLayout page=new LinearLayout(this);page.setOrientation(1);page.setPadding(40,70,40,40);page.setBackgroundColor(0xfffafafa);page.setFitsSystemWindows(true);TextView title=new TextView(this);title.setText("Дом с Алисой");title.setTextSize(27);title.setTextColor(0xff27232e);page.addView(title);message=new TextView(this);message.setText("Подготавливаем защищённое подключение…");message.setTextSize(16);message.setPadding(0,32,0,32);page.addView(message);Button close=new Button(this);close.setText("Вернуться в AliceKit");close.setOnClickListener(v->finish());page.addView(close);setContentView(page);handle(getIntent());}
 @Override public void onNewIntent(Intent intent){super.onNewIntent(intent);setIntent(intent);handle(intent);}
 private static String random(){byte[] b=new byte[32];new SecureRandom().nextBytes(b);return Base64.encodeToString(b,Base64.URL_SAFE|Base64.NO_WRAP|Base64.NO_PADDING);}
 private void note(String value){runOnUiThread(()->message.setText(value));}
 private void handle(Intent intent){if(running)return;running=true;final Uri callback=intent.getData();new Thread(()->{try{SecureStore store=new SecureStore(this);String saved=store.load();if(saved==null)throw new IOException("Сначала подключите телефон к станции.");JSONObject station=new JSONObject(saved);
 if(callback==null){JSONObject channel=PublicUpdates.manifest(),config=channel.optJSONObject("yandexOAuth");String id=config==null?"":config.optString("clientId");if(!id.matches("[a-fA-F0-9]{32,64}"))throw new IOException("Общий вход через Яндекс ещё не активирован для этого выпуска. Ожидается регистрация приложения AliceKit; пользователям создавать своё приложение не потребуется.");String state=random(),verifier=random(),challenge=Base64.encodeToString(MessageDigest.getInstance("SHA-256").digest(verifier.getBytes("US-ASCII")),Base64.URL_SAFE|Base64.NO_WRAP|Base64.NO_PADDING);JSONObject pending=new JSONObject();pending.put("state",state);pending.put("verifier",verifier);pending.put("clientId",id);pending.put("createdAt",System.currentTimeMillis());pending.put("host",station.getString("host"));pending.put("pin",station.getString("pin"));store.savePrivate("home-auth",pending.toString());Uri url=Uri.parse("https://oauth.yandex.ru/authorize").buildUpon().appendQueryParameter("response_type","code").appendQueryParameter("client_id",id).appendQueryParameter("redirect_uri",REDIRECT).appendQueryParameter("scope","iot:view iot:control").appendQueryParameter("force_confirm","yes").appendQueryParameter("state",state).appendQueryParameter("code_challenge",challenge).appendQueryParameter("code_challenge_method","S256").build();note("Подтвердите в Яндексе просмотр и управление своим домом. После подтверждения вернитесь в AliceKit.");runOnUiThread(()->startActivity(new Intent(Intent.ACTION_VIEW,url)));return;}
 if(!REDIRECT.equals(callback.buildUpon().clearQuery().fragment(null).build().toString())||!Intent.ACTION_VIEW.equals(intent.getAction()))throw new IOException("Некорректный ответ авторизации");String value=store.loadPrivate("home-auth");if(value==null)throw new IOException("Запрос входа уже завершён или не запускался. Начните подключение заново.");JSONObject pending=new JSONObject(value);String returned=callback.getQueryParameter("state");if(returned==null||!MessageDigest.isEqual(returned.getBytes("UTF-8"),pending.getString("state").getBytes("UTF-8")))throw new IOException("Ответ Яндекса не относится к текущему подключению");long age=System.currentTimeMillis()-pending.getLong("createdAt");if(age<0||age>600000||!station.getString("host").equals(pending.getString("host"))||!station.getString("pin").equals(pending.getString("pin")))throw new IOException("Запрос устарел или была выбрана другая станция");store.clearPrivate("home-auth");if(callback.getQueryParameter("error")!=null)throw new IOException("Доступ к дому не предоставлен. Его можно подключить позже.");String code=callback.getQueryParameter("code");if(code==null||code.length()>2048)throw new IOException("В ответе нет кода подтверждения");note("Подключаем устройства вашего дома…");String form="grant_type=authorization_code&code="+URLEncoder.encode(code,"UTF-8")+"&client_id="+URLEncoder.encode(pending.getString("clientId"),"UTF-8")+"&code_verifier="+URLEncoder.encode(pending.getString("verifier"),"UTF-8")+"&redirect_uri="+URLEncoder.encode(REDIRECT,"UTF-8");HttpsURLConnection exchange=(HttpsURLConnection)new URL("https://oauth.yandex.ru/token").openConnection();exchange.setInstanceFollowRedirects(false);exchange.setConnectTimeout(12000);exchange.setReadTimeout(20000);exchange.setRequestMethod("POST");exchange.setDoOutput(true);exchange.setRequestProperty("Content-Type","application/x-www-form-urlencoded");JSONObject token;try{try(OutputStream out=exchange.getOutputStream()){out.write(form.getBytes("UTF-8"));}if(exchange.getResponseCode()!=200)throw new IOException("Яндекс не подтвердил вход. Начните подключение заново.");token=new JSONObject(new String(read(exchange.getInputStream()),"UTF-8"));}finally{exchange.disconnect();}String oauth=token.getString("access_token");upload(station,oauth);note("Дом подключён. Устройства доступны в AliceKit и в плагинах, которым вы разрешили доступ. Вернитесь в панель и нажмите «Обновить устройства».");
 }catch(Exception e){note(e.getMessage()==null?"Не удалось завершить вход. Повторите подключение из панели.":e.getMessage());}finally{running=false;}},"alicekit-yandex-oauth").start();}
 private static byte[] read(InputStream in)throws Exception{try(InputStream source=in;ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=source.read(b))!=-1){out.write(b,0,n);if(out.size()>262144)throw new IOException("Слишком большой ответ сервиса");}return out.toByteArray();}}
 private static void upload(JSONObject station,String token)throws Exception{String host=station.getString("host"),pin=station.getString("pin");InetAddress ip=InetAddress.getByName(host);if(!host.matches("[0-9.]+")||!(ip instanceof Inet4Address)||!ip.isSiteLocalAddress())throw new IOException("Неверный адрес станции");SSLContext context=SSLContext.getInstance("TLS");context.init(null,new TrustManager[]{new X509TrustManager(){public X509Certificate[]getAcceptedIssuers(){return new X509Certificate[0];}public void checkClientTrusted(X509Certificate[] c,String a)throws CertificateException{throw new CertificateException();}public void checkServerTrusted(X509Certificate[] chain,String auth)throws CertificateException{try{chain[0].checkValidity();String hash=PublicUpdates.hex(MessageDigest.getInstance("SHA-256").digest(chain[0].getEncoded()));if(!MessageDigest.isEqual(hash.getBytes("US-ASCII"),pin.getBytes("US-ASCII")))throw new CertificateException();}catch(Exception e){throw new CertificateException("Сертификат станции изменился");}}}},new SecureRandom());HttpsURLConnection connection=(HttpsURLConnection)new URL("https://"+host+":8789/api/home/account").openConnection();connection.setSSLSocketFactory(context.getSocketFactory());connection.setHostnameVerifier((h,s)->h.equals(host));connection.setConnectTimeout(5000);connection.setReadTimeout(20000);connection.setInstanceFollowRedirects(false);connection.setRequestMethod("POST");connection.setDoOutput(true);connection.setRequestProperty("Authorization","Bearer "+station.getString("token"));connection.setRequestProperty("Content-Type","application/json");try{JSONObject data=new JSONObject();data.put("token",token);try(OutputStream out=connection.getOutputStream()){out.write(data.toString().getBytes("UTF-8"));}int status=connection.getResponseCode();if(status!=200)throw new IOException("Станция не подтвердила подключение дома. Проверьте связь и версию агента.");read(connection.getInputStream());}finally{connection.disconnect();}}
}
